package com.vncode.app.integration.translation;
import okhttp3.*;
import okhttp3.mockwebserver.*;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class YandexNewsTranslatorTest {
 @Test void splitsTenThousandCharactersWithoutBreakingUnicode()throws Exception{try(var server=new MockWebServer()){server.start();server.setDispatcher(new okhttp3.mockwebserver.Dispatcher(){public MockResponse dispatch(RecordedRequest request){var body=JsonParser.parseString(request.getBody().readUtf8()).getAsJsonObject();var out=new JsonArray();int total=0;for(var text:body.getAsJsonArray("texts")){String value=text.getAsString();total+=value.length();assertFalse(Character.isHighSurrogate(value.charAt(value.length()-1)));var item=new JsonObject();item.addProperty("text",value);out.add(item);}assertTrue(total<=10000);var response=new JsonObject();response.add("translations",out);return new MockResponse().setBody(response.toString());}});String text="x"+"abc😀".repeat(5000);var client=new YandexNewsTranslator(new OkHttpClient(),server.url("/translate/v2/translate").uri(),"","secret-fixture",uri->"localhost".equals(uri.getHost()));assertEquals(List.of(text),client.translate(List.of(text),"ru","vi"));assertTrue(server.getRequestCount()>1);}}
 @Test void closingTranslatorStopsInFlightRequestAndFurtherChunks()throws Exception{try(var server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setSocketPolicy(SocketPolicy.NO_RESPONSE));var client=new YandexNewsTranslator(new OkHttpClient(),server.url("/translate/v2/translate").uri(),"","secret-fixture",uri->"localhost".equals(uri.getHost()));var task=new java.util.concurrent.FutureTask<List<String>>(() -> client.translate(List.of("x".repeat(20000)),"ru","vi"));Thread.ofVirtual().start(task);assertNotNull(server.takeRequest(2,java.util.concurrent.TimeUnit.SECONDS));client.close();assertThrows(java.util.concurrent.ExecutionException.class,()->task.get(3,java.util.concurrent.TimeUnit.SECONDS));assertEquals(1,server.getRequestCount());}}
 @Test void credentialNeverAppearsInTextOrErrors()throws Exception{try(var server=new MockWebServer()){server.start();server.enqueue(new MockResponse().setResponseCode(429).setBody("secret-fixture"));var client=new YandexNewsTranslator(new OkHttpClient(),server.url("/translate/v2/translate").uri(),"","secret-fixture",uri->"localhost".equals(uri.getHost()));var error=assertThrows(java.io.IOException.class,()->client.translate(List.of("GTIN 04612345678901"),"ru","vi"));assertFalse(error.toString().contains("secret-fixture"));var request=server.takeRequest();assertEquals("Api-Key secret-fixture",request.getHeader("Authorization"));assertFalse(request.getBody().readUtf8().contains("secret-fixture"));assertEquals(1,server.getRequestCount());}}
}
